package org.jlinalg.cli;

import static org.junit.jupiter.api.Assertions.*;
import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class FumaMagmaReportCliTest {
    @TempDir Path directory;
    private String message;
    private int run(String... args){var output=new ByteArrayOutputStream();var error=new ByteArrayOutputStream();try(var out=new PrintStream(output,true,StandardCharsets.UTF_8);var err=new PrintStream(error,true,StandardCharsets.UTF_8)){int code=FumaToolsCli.run(args,out,err);message=output.toString(StandardCharsets.UTF_8)+error.toString(StandardCharsets.UTF_8);return code;}}
    private int run(Map<String,String> options){var args=new ArrayList<String>();options.forEach((k,v)->{args.add("--"+k);args.add(v);});return run(args.toArray(String[]::new));}
    private Map<String,String> options(String name)throws Exception{return FumaMagmaReportTestData.options(directory.resolve(name));}
    private Path out(Map<String,String> options){return Path.of(options.get("out"));}
    private Map<?,?> session(Path out)throws Exception{return AdmixtureInputs.decode(Files.readAllBytes(out.resolve("session.json")));}
    private void failed(Map<String,String> options)throws Exception{assertEquals(2,run(options),message);Path out=out(options);assertTrue(Files.readString(out.resolve("WARNINGS.md")).contains("Required action"));assertTrue(Files.readString(out.resolve("analysis-status.json")).contains("failed"));assertFalse(Files.exists(out.resolve("sets-top.tsv")));assertTrue(Files.isDirectory(out.resolve("partial")));}
    @Test void actualDispatchWritesCompleteHolmTestsAndExplicitDisplayRows()throws Exception{var o=options("basic");assertEquals(0,run(o),message);Path out=out(o);assertEquals(4,Files.readAllLines(out.resolve("sets-all.tsv")).size());assertEquals(11,Files.readAllLines(out.resolve("sets-top.tsv")).size());assertEquals("B\t4\t.2\t.3\t.25\t.001\t0.003",Files.readAllLines(out.resolve("sets-top.tsv")).get(1));assertTrue(Files.readString(out.resolve("gene-joins.tsv")).contains("matched-empty-symbol"));assertEquals(3,((Number)session(out).get("finite_adjustment_family")).intValue());assertTrue(Files.readString(out.resolve("WARNINGS.md")).contains("HOLM DESPITE Pbon NAME"));}
    @Test void carrierPathsResolveRelativeAndEveryRawSnapshotMatches()throws Exception{var o=options("carrier");Path base=out(o).getParent();for(String key:List.of("gene-results","symbols","gsa","sets","out"))o.put(key,base.relativize(Path.of(o.get(key))).toString());Path carrier=FumaMagmaReportTestData.carrier(base.resolve("options.json"),o);assertEquals(0,run("--magma-report-options-file",carrier.toString()),message);var lines=Files.readAllLines(base.resolve("analysis/resource-ledger.tsv"));assertEquals(5,lines.size());for(String line:lines.subList(1,lines.size())){var fields=line.split("\t",-1);assertEquals(FollowupSupport.hash(Path.of(fields[1])),fields[3]);assertEquals(fields[3],FollowupSupport.hash(base.resolve("analysis").resolve(fields[2])));}}
    @Test void declaredGsaPreferenceDoesNotReadMissingFallback()throws Exception{var o=options("preference");assertFalse(Files.exists(Path.of(o.get("sets"))));assertEquals(0,run(o),message);assertEquals("gsa",session(out(o)).get("selected_set_source"));assertEquals(Boolean.TRUE,session(out(o)).get("ignored_sets_fallback"));assertFalse(Files.readString(out(o).resolve("resource-ledger.tsv")).contains("unused-and-absent"));assertTrue(Files.readString(out(o).resolve("WARNINGS.md")).contains("DECLARED GSA PREFERENCE"));}
    @Test void explicitFallbackUsesPlainTsv()throws Exception{var o=options("fallback");Path sets=out(o).getParent().resolve("sets.tsv");Files.writeString(sets,String.join("\n",Files.readAllLines(Path.of(o.get("gsa"))).subList(3,7))+"\n");o.put("gsa","none");o.put("sets",sets.toString());o.put("sets-format","tsv");assertEquals(0,run(o),message);assertEquals("sets",session(out(o)).get("selected_set_source"));}
    @Test void missingDeclaredGsaFailsInsteadOfSilentlyChoosingFallback()throws Exception{var o=options("missing-gsa");Files.writeString(Path.of(o.get("sets")),"would be ignored");o.put("gsa",out(o).getParent().resolve("missing.out").toString());failed(o);assertTrue(Files.readString(out(o).resolve("WARNINGS.md")).contains("supplied-gsa-set-results"));}
    @Test void duplicateAnnotationPolicyIsRequired()throws Exception{var o=options("duplicates");o.put("duplicates","error");failed(o);assertTrue(Files.readString(out(o).resolve("WARNINGS.md")).contains("Repeated annotation"));}
    @Test void missingPPolicyDoesNotInventFiniteTests()throws Exception{var o=options("missing");Path input=Path.of(o.get("gsa"));Files.writeString(input,Files.readString(input).replace("\t.001\n","\tNA\n"));o.put("missing-p","error");failed(o);o.put("out",out(o).resolveSibling("with-na").toString());o.put("missing-p","source-na");assertEquals(0,run(o),message);assertEquals(2,((Number)session(out(o)).get("finite_adjustment_family")).intValue());assertTrue(Files.readString(out(o).resolve("WARNINGS.md")).contains("MISSING P FAMILY"));}
    @Test void sourcePlaceholdersRequireExplicitChoice()throws Exception{var o=options("placeholders");o.put("placeholders","error");failed(o);assertTrue(Files.readString(out(o).resolve("WARNINGS.md")).contains("artificial all-missing"));}
    @Test void invalidPAndEmptyPopulationsFailWithRetainedInputCause()throws Exception{int i=0;for(String value:List.of("-.1","1.5","NaN","")){var o=options("bad-p-"+(i++));Path input=Path.of(o.get("gsa"));Files.writeString(input,Files.readString(input).replace("\t.001\n","\t"+value+"\n"));failed(o);}var empty=options("empty");Path input=Path.of(empty.get("gsa"));Files.writeString(input,String.join("\n",Files.readAllLines(input).subList(0,4))+"\n");failed(empty);assertTrue(Files.readString(out(empty).resolve("WARNINGS.md")).contains("Empty set population"));}
    @Test void malformedWidthDuplicateHeadersAndBadUtf8Fail()throws Exception{var o=options("width");Path symbols=Path.of(o.get("symbols"));Files.writeString(symbols,Files.readString(symbols)+"E3\n");failed(o);o=options("headers");symbols=Path.of(o.get("symbols"));Files.writeString(symbols,"ensembl_gene_id\tensembl_gene_id\nE1\tX\n");failed(o);o=options("encoding");Files.write(Path.of(o.get("symbols")),new byte[]{(byte)0xc3,(byte)0x28});failed(o);assertTrue(Files.readString(out(o).resolve("WARNINGS.md")).contains("Invalid UTF-8"));}
    @Test void magmaSkip3NeverSilentlyDropsUncommentedData()throws Exception{var o=options("comments");Path input=Path.of(o.get("gsa"));Files.writeString(input,Files.readString(input).replace("# no fit performed","not a comment"));failed(o);assertTrue(Files.readString(out(o).resolve("WARNINGS.md")).contains("magma-skip3 requires exactly three bounded initial comment lines"));}
    @Test void completeRowCellOperationAndOutputRowBoundsFail()throws Exception{for(var item:Map.of("max-rows","2","max-cells","10","max-operations","1","max-output-rows","1").entrySet()){var o=options(item.getKey());o.put(item.getKey(),item.getValue());failed(o);assertTrue(Files.readString(out(o).resolve("WARNINGS.md")).contains(item.getKey())||Files.readString(out(o).resolve("WARNINGS.md")).contains("capacity"));}}
    @Test void rawSnapshotAndScientificByteLimitsRetainFailureMetadata()throws Exception{for(String key:List.of("max-bytes","max-snapshot-bytes","max-output-bytes")){var o=options(key);o.put(key,"1");failed(o);assertTrue(Files.isRegularFile(out(o).resolve("session.json")));assertFalse(Files.exists(out(o).resolve("source-inputs")));}}
    @Test void emittedAndInputLineBoundsAreEnforced()throws Exception{var o=options("line");Path input=Path.of(o.get("gsa"));Files.writeString(input,Files.readString(input).replace("A\t3", "A".repeat(100)+"\t3"));o.put("max-line-bytes","64");failed(o);o=options("emitted-line");Files.writeString(Path.of(o.get("gene-results")),"GENE\tZSTAT\tP\tEXTRA\nE1\t2\t.02\t"+"e".repeat(30)+"\n");Files.writeString(Path.of(o.get("symbols")),"ensembl_gene_id\texternal_gene_name\nE1\t"+"s".repeat(44)+"\n");o.put("max-line-bytes","64");failed(o);assertTrue(Files.readString(out(o).resolve("WARNINGS.md")).contains("emitted MAGMA report row"));}
    @Test void recursiveUnknownAndNonstringOptionsFailBeforeOutput()throws Exception{var o=options("invalid-options");for(String key:List.of("magma-report-options-file","unknown-option","max-rows")){var bad=new LinkedHashMap<String,Object>(o);bad.put(key,key.equals("max-rows")?10:"bad");Path carrier=FumaMagmaReportTestData.carrier(directory.resolve(key+".json"),bad);assertEquals(2,run("--magma-report-options-file",carrier.toString()),message);assertTrue(message.contains("Required action"));assertFalse(Files.exists(out(o)));}}
    @Test void directOptionsOverrideCarrierAndMethodOverridesFail()throws Exception{var o=options("overrides");Path carrier=FumaMagmaReportTestData.carrier(directory.resolve("options.json"),o),actual=directory.resolve("overridden-output");assertEquals(0,run("--magma-report-options-file",carrier.toString(),"--out",actual.toString()),message);assertFalse(Files.exists(out(o)));assertTrue(Files.exists(actual.resolve("sets-top.tsv")));assertEquals(2,run("--magma-report-options-file",carrier.toString(),"--method","other"),message);}
    @Test void existingOutputsRemainUntouched()throws Exception{var o=options("existing");Files.createDirectory(out(o));Files.writeString(out(o).resolve("sentinel"),"unchanged");assertEquals(2,run(o),message);assertEquals("unchanged",Files.readString(out(o).resolve("sentinel")));try(var files=Files.list(out(o))){assertEquals(1,files.count());}}
    @Test void readerRechecksBothOriginalAndRawSnapshotIdentity()throws Exception{for(boolean snapshot:List.of(false,true)){Path root=directory.resolve("verify-"+snapshot);Files.createDirectory(root);Path source=directory.resolve("source-"+snapshot);Files.writeString(source,"A\n1\n");var input=new FumaMagmaReportInputs(root,new FumaMagmaReportInputs.Limits(1000,100,1000,1000,10000,10000),()->{});input.raw(source,"test",1000);Path changed=snapshot?root.resolve("source-inputs/i0001.raw"):source;Files.writeString(changed,"altered");assertThrows(Exception.class,input::verify);}}
    @Test void unicodeResourceAndOutputParentsWorkViaUtf8Carrier()throws Exception{var o=options("日本語-data");Path output=directory.resolve("β-output/結果");o.put("out",output.toString());Path carrier=FumaMagmaReportTestData.carrier(directory.resolve("ascii-options.json"),o);assertEquals(0,run("--magma-report-options-file",carrier.toString()),message);assertTrue(Files.isRegularFile(output.resolve("genes.tsv")));}
    @Test void independentParentReportCompletesAfterAnotherNativeFailure()throws Exception{var o=options("parent-failure");Path base=out(o).getParent(),recipe=FumaMagmaReportTestData.parent(base,o,Map.of("variant_annotation",Map.of("build","synthetic-v1")));assertEquals(2,run("--method","workflow","--workflow-options-file",recipe.toString()),message);assertTrue(Files.exists(base.resolve("workflow/magma-report/sets-top.tsv")));String journal=Files.readString(base.resolve("workflow/workflow-journal.json"));assertTrue(journal.contains("magma-report"));assertTrue(journal.contains("failed"));}
    @Test void independentParentReportCompletesAfterExternalMagmaSkip()throws Exception{var o=options("parent-skip");Path base=out(o).getParent();var annotate=Map.of("method","annotate","home",base.resolve("unavailable-home").toString(),"snps",base.resolve("unavailable-snps").toString(),"genes",base.resolve("unavailable-genes").toString());Path recipe=FumaMagmaReportTestData.parent(base,o,Map.of("magma_annotate",annotate));assertEquals(3,run("--method","workflow","--workflow-options-file",recipe.toString()),message);assertTrue(Files.exists(base.resolve("workflow/magma-report/sets-top.tsv")));assertTrue(Files.readString(base.resolve("workflow/magma-annotation/WARNINGS.md")).contains("Required action"));}
    @Test void parentMethodBuildAndRecursiveCarrierOverridesAreRejected()throws Exception{for(String field:List.of("method","build","magma-report-options-file")){var o=options("parent-bad-"+field);o.put(field,"wrong");Path base=out(o).getParent(),recipe=FumaMagmaReportTestData.parent(base,o,Map.of());assertEquals(2,run("--method","workflow","--workflow-options-file",recipe.toString()),message);assertFalse(Files.exists(base.resolve("workflow")));}}
    @Test void allMissingPAndZeroPProduceProminentInterpretationWarnings()throws Exception{var o=options("no-evidence");Path input=Path.of(o.get("gsa"));Files.writeString(input,Files.readString(input).replace("\t.2\n","\tNA\n").replace("\t.001\n","\tNA\n").replace("\t.03\n","\tNA\n"));assertEquals(0,run(o),message);assertEquals(0,((Number)session(out(o)).get("finite_adjustment_family")).intValue());assertTrue(Files.readString(out(o).resolve("WARNINGS.md")).contains("NO FINITE SET TESTS"));o=options("zero-p");input=Path.of(o.get("gsa"));Files.writeString(input,Files.readString(input).replace("\t.001\n","\t0\n"));assertEquals(0,run(o),message);assertTrue(Files.readString(out(o).resolve("WARNINGS.md")).contains("ZERO/UNDERFLOW P"));}
    @Test void resourceSymbolNAIsRetainedAsTheFirstMatchAndBytesAreAccounted()throws Exception{var o=options("null-symbol");Path symbols=Path.of(o.get("symbols"));Files.writeString(symbols,Files.readString(symbols).replace("E1\tFirst","E1\tNA"));assertEquals(0,run(o),message);assertTrue(Files.readAllLines(out(o).resolve("genes.tsv")).get(1).endsWith("\tNA"));assertTrue(Files.readString(out(o).resolve("gene-joins.tsv")).contains("matched-missing-symbol"));long bytes;try(var files=Files.walk(out(o))){bytes=files.filter(Files::isRegularFile).filter(p->p.toString().endsWith(".tsv")||p.getParent().getFileName().toString().equals("source-inputs")).mapToLong(p->{try{return Files.size(p);}catch(Exception failure){throw new IllegalStateException(failure);}}).sum();}assertEquals(bytes,((Number)session(out(o)).get("scientific_files_and_snapshot_bytes")).longValue());}
}
